package app.streamnest;
import java.util.*;import java.util.regex.Pattern;import java.text.Normalizer;import java.util.concurrent.*;import org.json.*;
final class HomeSearch {
 static final ThreadPoolExecutor worker=new ThreadPoolExecutor(3,3,30,TimeUnit.SECONDS,new ArrayBlockingQueue<>(6));static{worker.allowCoreThreadTimeOut(true);}
 interface Provider{List<Catalog.Title> get(String kind,int page,String query)throws Exception;}static volatile Provider testProvider;
 static final Pattern MARKS=Pattern.compile("\\p{M}+"),WORDS=Pattern.compile("[^\\p{L}\\p{N}]+");
 static String normalize(String s){return WORDS.matcher(MARKS.matcher(Normalizer.normalize(s==null?"":s,Normalizer.Form.NFKD)).replaceAll("").toLowerCase(Locale.ROOT)).replaceAll(" ").trim();}
 static int score(Catalog.Title t,String q){if(t.id.equals(q))return 0;String query=normalize(q);if(query.isEmpty())return 99;List<String> names=new ArrayList<>(Arrays.asList(t.title,t.raw.optString("name")));JSONArray aliases=t.raw.optJSONArray("aliases");if(aliases!=null)for(int i=0;i<Math.min(20,aliases.length());i++)names.add(aliases.optString(i));int best=99;for(String raw:names){String name=normalize(raw);int rank=99;if(name.equals(query))rank=0;else if(name.startsWith(query))rank=1;else if(name.contains(query))rank=2;else{boolean all=true;for(String word:query.split(" "))all&=name.contains(word);if(all)rank=3;}best=Math.min(best,rank);}return best;}
 static List<Catalog.Title> merge(List<Catalog.Title> pool){Map<String,Catalog.Title> ids=new LinkedHashMap<>();for(Catalog.Title t:pool){if(!t.id.matches("tt[0-9]+"))continue;Catalog.Title old=ids.get(t.id);if(old==null||!old.kind.equals("animes")||t.kind.equals("animes"))ids.put(t.id,t);}return new ArrayList<>(ids.values());}
 static List<Catalog.Title> matches(List<Catalog.Title> pool,String q){List<Catalog.Title> found=new ArrayList<>();Map<String,Integer> scores=new HashMap<>();for(Catalog.Title t:merge(pool)){int rank=score(t,q);if(rank<99){found.add(t);scores.put(t.id,rank);}}found.sort(Comparator.comparingInt((Catalog.Title t)->scores.get(t.id)).thenComparing(t->t.title).thenComparing(t->t.id));return found;}
 static List<HomeFeed.Row> rows(List<Catalog.Title> pool,String q,int page,int size){List<Catalog.Title> found=matches(pool,q);List<HomeFeed.Row> rows=new ArrayList<>();for(String kind:new String[]{"movies","shows","animes"}){List<HomeFeed.Card> cards=new ArrayList<>();int n=0,start=(page-1)*size;for(Catalog.Title t:found)if(t.kind.equals(kind)&&n++>=start&&cards.size()<size)cards.add(new HomeFeed.Card(t,null,""));rows.add(new HomeFeed.Row(kind.equals("movies")?"Movies":kind.equals("shows")?"Series":"Anime",cards));}return rows;}
 static boolean more(List<Catalog.Title> pool,String q,int page,int size){List<Catalog.Title> found=matches(pool,q);for(String kind:new String[]{"movies","shows","animes"}){int n=0;for(Catalog.Title t:found)if(t.kind.equals(kind))n++;if(n>page*size)return true;}return false;}
 static List<Catalog.Title> fetch(String kind,int page,String q,String base)throws Exception{if(testProvider!=null)return testProvider.get(kind,page,q);if(kind.equals("animes"))return AnimeCatalog.list(page,q,"trending","All","All",-1);if(!Catalog.legacy(base))return Catalog.list(base,kind,page,q,"trending","All","All",-1);return kind.equals("movies")?PagedMovies.list(page,q,"trending","All","All","all",-1,false):SeriesIndex.list(base,page,q,"trending","All","all",-1);}
}
